#include <stdio.h>

int main(void) {
    int n;
    scanf("%d", &n);
    long tong = 0;
    for (int i = 0; i < n; i++) {
        int t;
        scanf("%d", &t);
        tong += t;
    }
    long tb = tong / n;
    if (tb < 500) printf("nhanh %ld\n", tb);
    else printf("cham %ld\n", tb);
    return 0;
}
